-- The original meals entry claimed snacks/menu/allergies/nutrition, which the
-- more specific nutrition entries below cover better. Narrow it so it stays the
-- general "do you provide meals" answer and stops shadowing them.
UPDATE chatbot_faq
SET keywords = 'meal,meals,lunch,breakfast,dinner,halal,vegetarian,vegan,diet,dietary,feeding'
WHERE category = 'meals';

ON CONFLICT DO NOTHING;
